def normalize_statuses(apps, schema_editor):
    Player = apps.get_model("db", "RosterPlayer")
    Event = apps.get_model("db", "RosterEvent")
    # Snapshot legacy inactive jerseys before releasing them: gateway tags may
    # contain only these numbers, so absence of an Issue FK is not proof of no use.
    for player in (
        Player.objects.filter(status__in=["inactive", "removed"])
        .exclude(jersey_number__isnull=True)
        .exclude(jersey_number="")
    ):
        Event.objects.create(
            project_id=player.project_id,
            workspace_id=player.workspace_id,
            roster_player_id=player.id,
            roster_identity=player.id,
            player_name=player.player_name,
            jersey_number=player.jersey_number,
            action="imported",
            previous_status=player.status,
            status=player.status,
        )
    Player.objects.filter(status="injured").update(status="active")
    Player.objects.filter(status__in=["inactive", "removed"]).update(jersey_number=None)


